package com.dvopenlabs.freedom.companions;
import android.content.Intent;
import android.widget.TextView;
import org.json.JSONObject;
import java.io.File;
import java.util.*;
/** An explicitly requested small museum selection, never an automatic background art feed. */
public final class ArtGalleryActivity extends PanelActivity {
    @Override void home(){page("Museum art","Optional Met Open Access selection. Loading sends requests to collectionapi.metmuseum.org; downloading an image contacts images.metmuseum.org. Only images marked public domain are accepted. No account or key is required. Nothing downloads on open.",false);button("Load museum selection",this::catalogue);button("Preview cached art",()->startActivity(new Intent(this,AmbientActivity.class).putExtra("art-preview",true)));button("Photo & Art appearance",()->startActivity(new Intent(this,AmbientSettingsActivity.class)));for(File f:MuseumArt.photos(this)){JSONObject m=PhotoLibrary.metadata(f);page.addView(text(m.optString("title")+" · "+m.optString("credit"),17));}button("Clear cached art",()->{for(File f:MuseumArt.photos(this)){f.delete();new File(f.getParentFile(),f.getName().replace(".jpg",".json")).delete();}home();});button("Back",this::finish);}
    void catalogue(){page("Met Open Access selection","Select an artwork to cache it. This never selects a wallpaper or system screensaver. Museum metadata/images may be unavailable; only public-domain responses are accepted.",false);TextView status=text("Loading three records…",17);page.addView(status);load(()->{List<JSONObject> results=new ArrayList<>();for(int id:MuseumArt.OBJECTS){if(Thread.currentThread().isInterrupted())break;try{results.add(MuseumArt.object(id));}catch(Exception unavailable){}}return results;},items->{status.setText(items.isEmpty()?"No public-domain images available. Try again later.":"Choose an artwork to download, up to 4 MB.");for(JSONObject o:items)button(o.optString("title")+" · "+o.optString("artistDisplayName"),()->{int token=generation;status.setText("Caching selected artwork…");load(()->{MuseumArt.download(this,o,()->visible&&generation==token);return true;},ok->status.setText("Artwork cached. Choose Museum art in Photo & Art appearance to preview it."),bad->status.setText("Image unavailable. Your previous art and wallpaper stay saved."));});},bad->status.setText("Museum unavailable. Try again later."));button("Back",this::home);}
}
